<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {BotPermissionsClient,type BotPermissionState,type BotRole} from './bot-permissions-client';
 export let companyId:string;export let botId:string;export let botName='this agent';export let accessSignal:AbortSignal;export let membershipRevision=0;export let effectiveCapabilities:string[]=[];
 const dispatch=createEventDispatcher();let client:BotPermissionsClient|null=null,boundSignal:AbortSignal|undefined,ready=false,scope='',loading=true,busy=false,error='',notice='',state:BotPermissionState|null=null,selectedRole='',creating=false,roleName='',grants:string[]=[];
 const labels:Record<string,string>={'tools.dispatch':'Run tools','bots.run':'Run agent','computer.control':'Control company computer','computer.view':'View company computer','files.manage':'Manage files','messages.send':'Send messages','integrations.run':'Run integrations','bots.install':'Install bots'};
 const label=(permission:string)=>labels[permission]||permission.replaceAll('.',' · ');
 $: currentScope=JSON.stringify([companyId,botId,membershipRevision]);$: if(ready&&scope!==currentScope){scope=currentScope;void load();}
 $: available=state?.roles.filter(r=>r.kind==='bot'&&r.active&&r.grants.every(g=>state?.permissions.some(p=>p.name===g&&p.delegable)))||[];
 $: selected=available.find(r=>r.id===selectedRole);
 $: effective=state?.effective??effectiveCapabilities;
 $: assigned=state?.assignedRoleIds===null?null:state?.roles.filter(r=>state?.assignedRoleIds?.includes(r.id))||[];
 function revoke(status=403){client?.close();client=null;state=null;selectedRole='';roleName='';grants=[];busy=false;loading=false;notice='';error='Company access changed. Reopen your workspace.';dispatch('accesschanged',{status});}
 function parentRevoked(){revoke();}
 $: if(ready&&boundSignal!==accessSignal){boundSignal?.removeEventListener('abort',parentRevoked);boundSignal=accessSignal;boundSignal?.addEventListener('abort',parentRevoked,{once:true});if(boundSignal?.aborted)parentRevoked();}
 async function load(){if(accessSignal?.aborted){revoke();return;}client?.close();const current=client=new BotPermissionsClient(companyId,botId,()=>localStorage.token||'');loading=true;state=null;error='';notice='';selectedRole='';try{const value=await current.load();if(current===client)state=value;}catch(e){if(current===client){if([401,403].includes((e as any).status))revoke((e as any).status);else error=(e as Error).message;}}finally{if(current===client)loading=false;}}
 async function apply(role:BotRole,remove=false){if(!client||busy)return;const current=client;busy=true;error='';notice='';try{const value=await current.apply(role,remove);if(current!==client)return;state=value;selectedRole='';notice=remove?'Role assignment removed.':'Role applied. Effective permissions refreshed.';dispatch('changed',{companyId,botId,effectiveCapabilities:value.effective});}catch(e){if(current===client){if([401,403].includes((e as any).status))revoke((e as any).status);else error=(e as Error).message+' Reload to reconcile the current assignment.';}}finally{if(current===client)busy=false;}}
 async function createRole(){if(!client||busy)return;const current=client;busy=true;error='';notice='';try{const role=await current.createRole(roleName,grants);if(current!==client)return;const value=await current.load();if(current!==client)return;state=value;selectedRole=role.id;roleName='';grants=[];creating=false;notice='Bot role created. Review it and click Apply role to grant its permissions.';}catch(e){if(current===client){if([401,403].includes((e as any).status))revoke((e as any).status);else error=(e as Error).message;}}finally{if(current===client)busy=false;}}
 function session(e:StorageEvent){if(e.key==='token'||e.key===null)revoke(401);}
 onMount(()=>{ready=true;window.addEventListener('storage',session);return()=>window.removeEventListener('storage',session);});onDestroy(()=>{client?.close();boundSignal?.removeEventListener('abort',parentRevoked);});
</script>

<section class="bot-permissions" aria-label="Bot permissions" aria-busy={busy||loading}>
 <h2>Permissions</h2><p class="intro">Give {botName} only the access needed for its work. Instructions never grant tool access.</p>
 {#if error}<div class="alert" role="alert">{error}</div>{/if}{#if notice}<div class="notice" role="status">{notice}</div>{/if}
 {#if loading}<p class="muted" role="status">Checking company roles and agent permissions…</p>{:else if state}
 <h3>Effective access</h3><div class="chips">{#each effective as permission}<span>{label(permission)}</span>{/each}</div>{#if !effective.length}<p class="muted">No effective permissions were returned.</p>{/if}
 {#if state.canManage}<h3>Assigned roles</h3>{#if assigned===null}<p class="muted">Assigned role details are unavailable for this session. Effective permissions are shown above; assignments are not inferred from overlapping grants.</p>{:else if assigned.length}<div class="assignments">{#each assigned as role}<article><div><strong>{role.name}</strong><p>{role.grants.map(label).join(' · ')||'No additional permissions'}{!role.active?' · Inactive':''}</p></div>{#if role.active}<button class="secondary" disabled={busy} on:click={()=>apply(role,true)}>Remove</button>{/if}</article>{/each}</div>{:else}<p class="muted">No custom bot roles are assigned.</p>{/if}
 <form on:submit|preventDefault={()=>selected&&apply(selected)}><label for="bot-role">Assign a bot role</label><select id="bot-role" bind:value={selectedRole} disabled={busy}><option value="">Choose a company bot role</option>{#each available as role}<option value={role.id}>{role.name}</option>{/each}</select>{#if selected}<div class="preview"><strong>This role grants</strong><div class="chips">{#each selected.grants as permission}<span>{label(permission)}</span>{/each}</div></div>{/if}<div class="actions"><button class="primary" disabled={busy||!selected}>{busy?'Saving…':'Apply role'}</button><button type="button" class="text-button" disabled={busy} on:click={()=>creating=!creating}>{creating?'Cancel new role':'Create a bot role'}</button></div></form>
 {#if creating}<form class="new-role" on:submit|preventDefault={createRole}><h3>New bot role</h3><p class="muted">Creating a role does not assign it. Only permissions marked delegable by the server are listed.</p><label for="bot-role-name">Role name</label><input id="bot-role-name" bind:value={roleName} maxlength="100" required disabled={busy}/><fieldset><legend>Choose permissions</legend>{#each state.permissions.filter(p=>p.delegable) as permission}<label class="permission"><input type="checkbox" bind:group={grants} value={permission.name} disabled={busy}/><span>{label(permission.name)}<small>{permission.name}</small></span></label>{/each}</fieldset><button class="secondary" disabled={busy||!roleName.trim()||!grants.length}>{busy?'Saving…':'Create role'}</button></form>{/if}
 {:else}<p class="muted">Company owners and admins manage bot role assignments.</p>{/if}
 {/if}{#if !loading&&client}<button class="text-button reload" disabled={busy} on:click={load}>Reload current permissions</button>{/if}
</section>

<style>
 .bot-permissions{color:#17243F;max-width:760px}h2{font-size:20px;font-weight:600;margin:0 0 9px;letter-spacing:-.3px}h3{font-size:13px;font-weight:600;margin:26px 0 12px}.intro,.muted{font-size:12px;line-height:1.75;color:#71809A;margin:8px 0 15px}.chips{display:flex;gap:7px;flex-wrap:wrap}.chips span{font-size:11px;background:#F6F8FC;border:1px solid #E6EBF4;padding:6px 9px;border-radius:6px}.assignments article{display:flex;align-items:center;justify-content:space-between;gap:16px;border:1px solid #E6EBF4;border-radius:9px;padding:14px;margin-bottom:9px}.assignments strong{font-size:13px;font-weight:500}.assignments p{font-size:11px;line-height:1.7;color:#71809A;margin:5px 0 0}form{margin-top:22px}label{display:block;font-size:12px;font-weight:500;margin-bottom:9px}select,input:not([type=checkbox]){box-sizing:border-box;width:100%;border:1px solid #E6EBF4;background:white;color:#17243F;border-radius:8px;padding:11px 12px;font:inherit;font-size:12px;outline:none}select:focus,input:focus{border-color:#3466F6}.preview{padding:14px;background:#F6F8FC;border-radius:8px;margin-top:13px}.preview>strong{display:block;font-size:11px;margin-bottom:9px;font-weight:500}.actions{display:flex;align-items:center;gap:18px;margin-top:18px}.primary,.secondary{padding:10px 16px;border-radius:8px;font-size:12px;font-weight:500;cursor:pointer;white-space:nowrap}.primary{background:#3466F6;color:white;border:1px solid #3466F6}.secondary{background:white;color:#17243F;border:1px solid #E6EBF4}.text-button{background:none;border:0;color:#3466F6;font-size:12px;padding:0;cursor:pointer}.reload{margin-top:25px}.new-role{border-top:1px solid #E6EBF4;padding-top:4px}.new-role input:not([type=checkbox]){margin-bottom:15px}fieldset{border:1px solid #E6EBF4;border-radius:9px;padding:14px;display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:15px}legend{font-size:11px;color:#71809A;padding:0 6px}.permission{display:flex;align-items:flex-start;gap:9px;margin:0;font-size:12px;font-weight:400}.permission input{accent-color:#3466F6;margin-top:3px}.permission small{display:block;font-size:10px;color:#71809A;margin-top:4px}.alert,.notice{font-size:12px;padding:12px 14px;border-radius:8px;line-height:1.7;margin:16px 0}.alert{background:#FFF4F4;border:1px solid #F3D2D5;color:#A62D35}.notice{background:#EFF8F2;border:1px solid #D8EDDF;color:#286A46}button:disabled,select:disabled,input:disabled{opacity:.5;cursor:default}button:focus-visible{outline:2px solid #3466F6;outline-offset:3px}@media(max-width:600px){fieldset{grid-template-columns:1fr}.assignments article{align-items:flex-start}.actions{flex-wrap:wrap}}
</style>

